WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions'),
il AS (SELECT il.*, i.paid_at, i.created_at icr FROM invoice_lots il JOIN invoices i ON i.id=il.invoice_id, op WHERE i.operator_id=op.id AND i.created_at>=now()-interval '84 days' AND i.status::text <> 'canceled')
SELECT
(SELECT json_build_object('refunded_lines', count(*), 'never_picked', count(*) FILTER (WHERE picked_up_at IS NULL), 'after_pickup', count(*) FILTER (WHERE picked_up_at IS NOT NULL AND refunded_at>picked_up_at), 'hammer_c', sum(winning_bid_cents), 'hammer_never_picked_c', sum(winning_bid_cents) FILTER (WHERE picked_up_at IS NULL), 'lot_marked_missing_or_removed', count(*) FILTER (WHERE l.removal_kind IS NOT NULL), 'lot_flagged_disposal', count(*) FILTER (WHERE l.flagged_for_disposal), 'p50_hours_close_to_refund', percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM il.refunded_at-il.icr)/3600)) FROM il JOIN lots l ON l.id=il.lot_id WHERE il.refunded_at IS NOT NULL) refunds,
(SELECT json_agg(x) FROM (SELECT coalesce(l.removal_kind,'none') k, count(*) n FROM il JOIN lots l ON l.id=il.lot_id WHERE il.refunded_at IS NOT NULL GROUP BY 1 ORDER BY 2 DESC LIMIT 8) x) refund_removal_kinds,
(SELECT json_build_object('relisted_closed', count(*), 'sold', count(*) FILTER (WHERE winner_bidder_id IS NOT NULL), 'avg_hammer_c', round(avg(current_bid_cents) FILTER (WHERE winner_bidder_id IS NOT NULL)), 'relist_2plus', count(*) FILTER (WHERE relist_count>=2), 'by_origin', (SELECT json_agg(y) FROM (SELECT coalesce(relist_origin,'none') o, count(*) n, count(*) FILTER (WHERE winner_bidder_id IS NOT NULL) sold, round(avg(current_bid_cents) FILTER (WHERE winner_bidder_id IS NOT NULL)) avg_c FROM lots, op WHERE lots.operator_id=op.id AND relisted_from_lot_id IS NOT NULL AND closed_at>=now()-interval '84 days' GROUP BY 1) y)) FROM lots, op WHERE lots.operator_id=op.id AND relisted_from_lot_id IS NOT NULL AND closed_at>=now()-interval '84 days') relists,
(SELECT json_build_object('zero_bid_lots', count(*), 'avg_msrp_c', round(avg(msrp_cents) FILTER (WHERE msrp_cents>0)), 'now_disposal_flagged', count(*) FILTER (WHERE flagged_for_disposal), 'top_cats', (SELECT json_agg(z) FROM (SELECT coalesce(category,'none') c, count(*) n FROM lots, op WHERE lots.operator_id=op.id AND closed_at>=now()-interval '84 days' AND winner_bidder_id IS NULL AND deleted_at IS NULL GROUP BY 1 ORDER BY 2 DESC LIMIT 6) z)) FROM lots, op WHERE lots.operator_id=op.id AND closed_at>=now()-interval '84 days' AND winner_bidder_id IS NULL AND deleted_at IS NULL) unsold,
(SELECT json_agg(x) FROM (SELECT w.name, count(l.id) lots, count(l.id) FILTER (WHERE l.closed_at IS NULL) open_lots, min(a.starts_at) first_start FROM warehouses w JOIN auctions a ON a.warehouse_id=w.id LEFT JOIN lots l ON l.auction_id=a.id WHERE w.name IN ('Crandall','Springdale','Dodge City') GROUP BY 1) x) other_sites
